import { DEFAULT_STATES, defaultColumnAccent, type ProjectCard, type StateConfig } from './data_types'

/** A status column with its cards already ordered by the `after` chain. */
export interface CardColumn {
    cards: ProjectCard[]
    status: string
}

/** Board column with its resolved configured accent. */
export interface BoardColumn extends CardColumn {
    color: string
}

/** A minimal header change produced by a drag: the fields a move rewrites. */
export interface CardMoveUpdate {
    after: string | null
    path: string
    status: string
}

/** Cards with a null/empty status share this column key so grouping stays total. */
export const UNASSIGNED_STATUS = ''

function statusOf(card: ProjectCard) {
    return card.header.status ?? UNASSIGNED_STATUS
}

/**
 * Order a single column's cards by the `after` chain, where a card's `after`
 * holds the `internalId` of the card that precedes it. Cards whose `after` is
 * empty or points outside the set are treated as heads (kept in input order),
 * and any cards left over by cycles or duplicate links are appended stably.
 */
export function orderByAfter(cards: ProjectCard[]): ProjectCard[] {
    const byInternalId = new Map<string, ProjectCard>()
    for (const card of cards) {
        if (card.header.internalId) byInternalId.set(card.header.internalId, card)
    }

    const followerOf = new Map<string, ProjectCard>()
    const heads: ProjectCard[] = []
    for (const card of cards) {
        const after = card.header.after
        if (after && byInternalId.has(after) && !followerOf.has(after)) {
            followerOf.set(after, card)
        } else {
            heads.push(card)
        }
    }

    const ordered: ProjectCard[] = []
    const visited = new Set<ProjectCard>()
    for (const head of heads) {
        let current: ProjectCard | undefined = head
        while (current && !visited.has(current)) {
            ordered.push(current)
            visited.add(current)
            current = current.header.internalId ? followerOf.get(current.header.internalId) : undefined
        }
    }
    for (const card of cards) {
        if (!visited.has(card)) ordered.push(card)
    }

    return ordered
}

/** Group cards into columns by distinct status, preserving first-seen order. */
export function groupByStatus(cards: ProjectCard[]): CardColumn[] {
    const order: string[] = []
    const buckets = new Map<string, ProjectCard[]>()

    for (const card of cards) {
        const status = statusOf(card)
        const bucket = buckets.get(status)
        if (bucket) {
            bucket.push(card)
        } else {
            buckets.set(status, [card])
            order.push(status)
        }
    }

    return order.map((status) => ({ cards: orderByAfter(buckets.get(status) ?? []), status }))
}

/** Build board columns in configured state order, omitting empty states unless they are always visible. */
export function buildCardColumns(cards: ProjectCard[], states: StateConfig[]): BoardColumn[] {
    return states
        .map(({ color, state }, index) => ({
            cards: orderByAfter(cards.filter((card) => statusOf(card) === state)),
            color: color ?? defaultColumnAccent(index),
            status: state,
        }))
        .filter((column, index) => states[index].alwaysVisible || column.cards.length > 0)
}

/** Derive state definitions from the distinct non-empty card states in first-seen order. */
export function deriveStatesFromCards(cards: ProjectCard[]): StateConfig[] {
    const states = cards
        .map((card) => statusOf(card))
        .filter((state, index, values) => state.length > 0 && values.indexOf(state) === index)

    return states.map((state, index) => ({ alwaysVisible: false, color: defaultColumnAccent(index), state }))
}

/** Keep discovered state order and append missing default state definitions. */
export function mergeStatesWithDefaults(states: StateConfig[]): StateConfig[] {
    const defaultsByState = new Map(DEFAULT_STATES.map((stateConfig) => [stateConfig.state, stateConfig]))
    const mergedStates = states.map((stateConfig, index) => defaultsByState.get(stateConfig.state) ?? {
        ...stateConfig,
        color: stateConfig.color ?? defaultColumnAccent(index),
    })
    const mergedStateNames = new Set(mergedStates.map(({ state }) => state))

    return [...mergedStates, ...DEFAULT_STATES.filter(({ state }) => !mergedStateNames.has(state))]
}

function clamp(value: number, min: number, max: number) {
    return Math.min(Math.max(value, min), max)
}

/**
 * Compute the minimal set of header changes to move `cardPath` into
 * `targetStatus` at `targetIndex`. At most three cards change: the moved card
 * (new `status` + `after`), the card that now follows it in the target column,
 * and the card that used to follow it in the source column. No-op moves and
 * links whose values are unchanged are filtered out so only affected cards are
 * written.
 */
export function computeMove(
    cards: ProjectCard[],
    cardPath: string,
    targetStatus: string,
    targetIndex: number,
): CardMoveUpdate[] {
    const moved = cards.find((card) => card.path === cardPath)
    if (!moved) return []

    const movedInternalId = moved.header.internalId
    const updates = new Map<string, CardMoveUpdate>()

    const sourceStatus = statusOf(moved)
    const sourceOrdered = orderByAfter(cards.filter((card) => statusOf(card) === sourceStatus))
    const movedPosition = sourceOrdered.findIndex((card) => card.path === cardPath)
    const oldFollower = sourceOrdered[movedPosition + 1]

    const targetOrdered = orderByAfter(
        cards.filter((card) => statusOf(card) === targetStatus && card.path !== cardPath),
    )
    const insertIndex = clamp(targetIndex, 0, targetOrdered.length)
    const newPredecessor = targetOrdered[insertIndex - 1] ?? null
    const newFollower = targetOrdered[insertIndex] ?? null

    updates.set(cardPath, { after: newPredecessor?.header.internalId ?? null, path: cardPath, status: targetStatus })

    if (newFollower && movedInternalId) {
        updates.set(newFollower.path, { after: movedInternalId, path: newFollower.path, status: targetStatus })
    }

    if (oldFollower && !updates.has(oldFollower.path)) {
        updates.set(oldFollower.path, { after: moved.header.after, path: oldFollower.path, status: sourceStatus })
    }

    const byPath = new Map(cards.map((card) => [card.path, card]))

    return [...updates.values()].filter((update) => {
        const card = byPath.get(update.path)
        if (!card) return true

        return card.header.after !== update.after || statusOf(card) !== update.status
    })
}

import { describe, expect, it } from 'vitest'
import { buildCardColumns, computeMove, deriveStatesFromCards, groupByStatus, mergeStatesWithDefaults, orderByAfter } from './card_ordering'
import { defaultColumnAccent, type ProjectCard } from './data_types'

function card(internalId: string, options: { after?: string | null; status?: string } = {}): ProjectCard {
    return {
        agentConversationErrors: [],
        agentConversations: [],
        headerFields: {},
        content: '',
        header: {
            affects: [],
            after: options.after ?? null,
            agentLogReferences: [],
            author: null,
            id: internalId.toUpperCase(),
            internalId,
            owner: null,
            policy: {},
            status: options.status ?? 'active',
            title: internalId,
        },
        isActive: true,
        path: `design/${internalId}.md`,
    }
}

function paths(cards: ProjectCard[]) {
    return cards.map((entry) => entry.header.internalId)
}

describe('orderByAfter', () => {
    it('orders cards by their after chain regardless of input order', () => {
        const cards = [card('c', { after: 'b' }), card('a'), card('d', { after: 'c' }), card('b', { after: 'a' })]

        expect(paths(orderByAfter(cards))).toEqual(['a', 'b', 'c', 'd'])
    })

    it('keeps heads in input order and appends cards left over by cycles', () => {
        const cards = [card('x', { after: 'y' }), card('y', { after: 'x' }), card('a')]

        expect(paths(orderByAfter(cards))).toEqual(['a', 'x', 'y'])
    })
})

describe('groupByStatus', () => {
    it('creates one ordered column per distinct status in first-seen order', () => {
        const cards = [
            card('b', { after: 'a', status: 'todo' }),
            card('p', { status: 'done' }),
            card('a', { status: 'todo' }),
        ]
        const columns = groupByStatus(cards)

        expect(columns.map((column) => column.status)).toEqual(['todo', 'done'])
        expect(paths(columns[0].cards)).toEqual(['a', 'b'])
        expect(paths(columns[1].cards)).toEqual(['p'])
    })
})

describe('buildCardColumns', () => {
    it('uses config order and hides empty states unless always visible', () => {
        const cards = [card('a', { status: 'in progress' }), card('b', { status: 'done' })]
        const states = [
            { alwaysVisible: true, color: '#111111', state: 'new' },
            { alwaysVisible: false, color: '#222222', state: 'done' },
            { alwaysVisible: false, state: 'design' },
            { alwaysVisible: true, color: '#444444', state: 'in progress' },
        ]

        const columns = buildCardColumns(cards, states)

        expect(columns.map((column) => column.status)).toEqual(['new', 'done', 'in progress'])
        expect(columns.map((column) => column.color)).toEqual(['#111111', '#222222', '#444444'])
        expect(columns.map((column) => paths(column.cards))).toEqual([[], ['b'], ['a']])
    })

    it('does not create columns for card states absent from config', () => {
        expect(buildCardColumns([card('a', { status: 'unsupported' })], [
            { alwaysVisible: true, state: 'new' },
        ])).toEqual([{ cards: [], color: defaultColumnAccent(0), status: 'new' }])
    })
})

describe('deriveStatesFromCards', () => {
    it('derives distinct non-empty states in first-seen order as non-persistent columns', () => {
        const cards = [
            card('a', { status: 'design' }),
            card('b', { status: 'ready' }),
            card('c', { status: 'design' }),
        ]

        expect(deriveStatesFromCards(cards)).toEqual([
            { alwaysVisible: false, color: defaultColumnAccent(0), state: 'design' },
            { alwaysVisible: false, color: defaultColumnAccent(1), state: 'ready' },
        ])
    })
})

describe('mergeStatesWithDefaults', () => {
    it('keeps discovered order, uses matching default definitions and appends missing defaults', () => {
        const states = [
            { alwaysVisible: false, state: 'custom' },
            { alwaysVisible: false, state: 'design' },
        ]

        expect(mergeStatesWithDefaults(states)).toEqual([
            { alwaysVisible: false, color: defaultColumnAccent(0), state: 'custom' },
            { alwaysVisible: true, color: defaultColumnAccent(1), state: 'design' },
            { alwaysVisible: true, color: defaultColumnAccent(0), state: 'new' },
            { alwaysVisible: true, color: defaultColumnAccent(2), state: 'ready for implementation' },
            { alwaysVisible: true, color: defaultColumnAccent(3), state: 'in progress' },
            { alwaysVisible: true, color: defaultColumnAccent(4), state: 'done' },
        ])
    })
})

describe('computeMove', () => {
    const column = [
        card('a'),
        card('b', { after: 'a' }),
        card('c', { after: 'b' }),
        card('d', { after: 'c' }),
    ]

    it('reorders within a column touching only the affected cards', () => {
        const updates = computeMove(column, 'design/c.md', 'active', 0)

        expect(updates).toHaveLength(3)
        expect(updates).toContainEqual({ after: null, path: 'design/c.md', status: 'active' })
        expect(updates).toContainEqual({ after: 'c', path: 'design/a.md', status: 'active' })
        expect(updates).toContainEqual({ after: 'b', path: 'design/d.md', status: 'active' })
    })

    it('moves a card to the end of its column with a minimal write set', () => {
        const updates = computeMove(column, 'design/b.md', 'active', 3)

        expect(updates).toHaveLength(2)
        expect(updates).toContainEqual({ after: 'd', path: 'design/b.md', status: 'active' })
        expect(updates).toContainEqual({ after: 'a', path: 'design/c.md', status: 'active' })
    })

    it('changes status and relinks both columns when moving across columns', () => {
        const cards = [
            card('a', { status: 'todo' }),
            card('b', { after: 'a', status: 'todo' }),
            card('c', { after: 'b', status: 'todo' }),
            card('p', { status: 'done' }),
            card('q', { after: 'p', status: 'done' }),
        ]
        const updates = computeMove(cards, 'design/b.md', 'done', 1)

        expect(updates).toHaveLength(3)
        expect(updates).toContainEqual({ after: 'p', path: 'design/b.md', status: 'done' })
        expect(updates).toContainEqual({ after: 'b', path: 'design/q.md', status: 'done' })
        expect(updates).toContainEqual({ after: 'a', path: 'design/c.md', status: 'todo' })
    })

    it('returns no updates for a no-op move', () => {
        expect(computeMove(column, 'design/b.md', 'active', 1)).toEqual([])
    })

    it('returns no updates when the card is not found', () => {
        expect(computeMove(column, 'design/missing.md', 'active', 0)).toEqual([])
    })
})

import type { CardColumn } from '../../data/card_ordering'
import type { CardTypeConfig } from '../../data/data_types'
import { getCardIdPrefix } from '../../data/card_identifiers'
import type { DragEndEvent, DragMoveEvent } from '@dnd-kit/core'

/** Droppable ids for empty/append targets are the status prefixed with this. */
export const COLUMN_DROP_PREFIX = 'column:'

/** Build the droppable id for a status column. */
export function columnDropId(status: string) {
    return `${COLUMN_DROP_PREFIX}${status}`
}

export interface DropTarget {
    targetIndex: number
    targetStatus: string
}

export type CardDropPlacement = 'after' | 'before'

export interface CardVerticalBounds {
    height: number
    top: number
}

type CardDragPositionEvent = DragEndEvent | DragMoveEvent

function getPointerY(event: CardDragPositionEvent): number {
    const { activatorEvent, delta } = event
    if (!('clientY' in activatorEvent) || typeof activatorEvent.clientY !== 'number') {
        throw new Error('Card dragging requires a pointer event with a vertical position')
    }

    return activatorEvent.clientY + delta.y
}

/** Resolve whether the pointer targets the half before or after a hovered card. */
export function getCardDropPlacement(pointerY: number, cardTop: number, cardHeight: number): CardDropPlacement {
    const cardMiddleY = cardTop + cardHeight / 2

    return pointerY < cardMiddleY ? 'before' : 'after'
}

/** Resolve a DnD event using stable drag-start bounds when available and current collision bounds otherwise. */
export function resolveCardDragEvent(
    columns: CardColumn[],
    event: CardDragPositionEvent,
    initialCardBounds: Map<string, CardVerticalBounds>,
): DropTarget | null {
    const { active, over } = event
    if (!over) return null

    const overId = String(over.id)
    const cardBounds = initialCardBounds.get(overId)
    const cardTop = cardBounds?.top ?? over.rect.top
    const cardHeight = cardBounds?.height ?? over.rect.height
    const pointerY = getPointerY(event)
    const cardDropPlacement = getCardDropPlacement(pointerY, cardTop, cardHeight)

    return resolveDrop(columns, String(active.id), overId, cardDropPlacement)
}

/**
 * Translate a drag end (active card path, the id it was dropped over) into the
 * target status and the insert index within the destination column's cards
 * excluding the dragged card. Returns null for a drop that changes nothing.
 */
export function resolveDrop(
    columns: CardColumn[],
    activePath: string,
    overId: string,
    cardDropPlacement: CardDropPlacement,
): DropTarget | null {
    if (activePath === overId) return null

    if (overId.startsWith(COLUMN_DROP_PREFIX)) {
        const status = overId.slice(COLUMN_DROP_PREFIX.length)
        const column = columns.find((entry) => entry.status === status)
        if (!column) return null

        const remaining = column.cards.filter((card) => card.path !== activePath)

        return { targetIndex: remaining.length, targetStatus: status }
    }

    const targetColumn = columns.find((entry) => entry.cards.some((card) => card.path === overId))
    if (!targetColumn) return null

    const remaining = targetColumn.cards.filter((card) => card.path !== activePath)
    const overIndex = remaining.findIndex((card) => card.path === overId)
    const targetIndex = overIndex === -1 ? remaining.length : overIndex + (cardDropPlacement === 'after' ? 1 : 0)

    return { targetIndex, targetStatus: targetColumn.status }
}

/** Resolve the configured type color for a card id via its prefix (e.g. `F-005` â†’ `F`). */
export function getCardTypeColor(cardTypes: CardTypeConfig[], id: string): string | undefined {
    const prefix = getCardIdPrefix(id)

    return cardTypes.find((cardType) => cardType.idPrefix === prefix)?.color
}

import { describe, expect, it } from 'vitest'
import type { DragMoveEvent } from '@dnd-kit/core'
import { columnDropId, getCardDropPlacement, getCardTypeColor, resolveCardDragEvent, resolveDrop } from './card_drag'
import type { CardColumn } from '../../data/card_ordering'
import type { CardTypeConfig, ProjectCard } from '../../data/data_types'

function card(path: string, internalId: string): ProjectCard {
    return {
        agentConversationErrors: [],
        agentConversations: [],
        headerFields: {},
        content: '',
        header: { affects: [], after: null, agentLogReferences: [], author: null, id: path, internalId, owner: null, policy: {}, status: 'todo', title: path },
        isActive: true,
        path,
    }
}

const columns: CardColumn[] = [
    { cards: [card('a', 'a'), card('b', 'b'), card('c', 'c')], status: 'todo' },
    { cards: [card('p', 'p'), card('q', 'q')], status: 'done' },
]

describe('resolveDrop', () => {
    it('returns null when dropped on itself', () => {
        expect(resolveDrop(columns, 'a', 'a', 'before')).toBeNull()
    })

    it('inserts before the card it is dropped over in the destination column', () => {
        expect(resolveDrop(columns, 'c', 'a', 'before')).toEqual({ targetIndex: 0, targetStatus: 'todo' })
    })

    it('inserts after the card it is dropped over in the destination column', () => {
        expect(resolveDrop(columns, 'a', 'p', 'after')).toEqual({ targetIndex: 1, targetStatus: 'done' })
    })

    it('appends after the final card in a destination column with two cards', () => {
        expect(resolveDrop(columns, 'a', 'q', 'after')).toEqual({ targetIndex: 2, targetStatus: 'done' })
    })

    it('appends to the end when dropped on a column container', () => {
        expect(resolveDrop(columns, 'a', columnDropId('done'), 'before')).toEqual({ targetIndex: 2, targetStatus: 'done' })
    })

    it('targets the destination column when dropped over a card in another column', () => {
        expect(resolveDrop(columns, 'a', 'p', 'before')).toEqual({ targetIndex: 0, targetStatus: 'done' })
    })
})

describe('getCardDropPlacement', () => {
    it('places the drop before a card when the pointer is in its top half', () => {
        expect(getCardDropPlacement(124, 100, 50)).toBe('before')
    })

    it('places the drop after a card when the pointer is in its bottom half', () => {
        expect(getCardDropPlacement(126, 100, 50)).toBe('after')
    })
})

describe('resolveCardDragEvent', () => {
    it('uses current collision bounds when target card has no drag-start measurement', () => {
        const event = {
            active: { id: 'a' },
            activatorEvent: { clientY: 100 },
            delta: { x: 0, y: 31 },
            over: { id: 'p', rect: { height: 60, top: 100 } },
        } as unknown as DragMoveEvent

        expect(resolveCardDragEvent(columns, event, new Map())).toEqual({ targetIndex: 1, targetStatus: 'done' })
    })
})

describe('getCardTypeColor', () => {
    const cardTypes: CardTypeConfig[] = [
        { color: '#111', idPrefix: 'F', label: 'Feature', type: 'feature' },
        { color: '#222', idPrefix: 'B', label: 'Bug', type: 'bug' },
    ]

    it('resolves the color from the id prefix', () => {
        expect(getCardTypeColor(cardTypes, 'F-005')).toBe('#111')
        expect(getCardTypeColor(cardTypes, 'F_005')).toBe('#111')
        expect(getCardTypeColor(cardTypes, 'B-3')).toBe('#222')
    })

    it('returns undefined for an unknown prefix', () => {
        expect(getCardTypeColor(cardTypes, 'X-1')).toBeUndefined()
    })
})

